31	import static org.elasticsearch.rest.RestRequest.INTERNAL_MARKER_REQUEST_PARAMETERS;
32	
33	public class RestUtils {
34	
35	    /**
36	     * Sets whether we decode a '+' in an url as a space or not.
37	     */
38	    private static final boolean DECODE_PLUS_AS_SPACE = Booleans.parseBoolean(System.getProperty("es.rest.url_plus_as_space", "false"));
39	
40	    public static final UnaryOperator<String> REST_DECODER = RestUtils::decodeComponent;
41	
42	    /**
43	     * Parses a URL-encoded query string into a multi-value map, preserving all values for
44	     * repeated parameters (e.g. {@code match[]=foo&match[]=bar} -> {@code ["foo", "bar"]}).
45	     *
46	     * @param s         the full string containing the query string
47	     * @param fromIndex the index at which the query string begins (i.e. one past the {@code ?})
48	     * @return a {@link RequestParams} from parameter name to all its values, in encounter order
49	     */
50	    static RequestParams decodeQueryString(String s, int fromIndex) {
51	        RequestParams params = RequestParams.empty();
52	        if (fromIndex < 0 || fromIndex >= s.length()) {
53	            return params;
54	        }
55	
56	        int queryStringLength = s.contains("#") ? s.indexOf('#') : s.length();
57	
58	        String name = null;
59	        int pos = fromIndex; // Beginning of the unprocessed region
60	        int i;       // End of the unprocessed region
61	        char c = 0;  // Current character
62	        for (i = fromIndex; i < queryStringLength; i++) {
63	            c = s.charAt(i);
64	            if (c == '=' && name == null) {
65	                if (pos != i) {
66	                    name = decodeQueryStringParam(s.substring(pos, i));
67	                }
68	                pos = i + 1;
69	            } else if (c == '&' || c == ';') {
70	                if (name == null && pos != i) {
71	                    // We haven't seen an `=' so far but moved forward.
72	                    // Must be a param of the form '&a&' so add it with
73	                    // an empty value.
74	                    addParam(params, decodeQueryStringParam(s.substring(pos, i)), "");
75	                } else if (name != null) {
76	                    addParam(params, name, decodeQueryStringParam(s.substring(pos, i)));
77	                    name = null;
78	                }
79	                pos = i + 1;
80	            }
81	        }
82	
83	        if (pos != i) {  // Are there characters we haven't dealt with?
84	            if (name == null) {     // Yes and we haven't seen any `='.
85	                addParam(params, decodeQueryStringParam(s.substring(pos, i)), "");
86	            } else {                // Yes and this must be the last value.
87	                addParam(params, name, decodeQueryStringParam(s.substring(pos, i)));
88	            }
89	        } else if (name != null) {  // Have we seen a name without value?
90	            addParam(params, name, "");
91	        }
92	
93	        return params;
94	    }
95	
96	    private static String decodeQueryStringParam(final String s) {
97	        return decodeComponent(s, StandardCharsets.UTF_8, true);
98	    }
99	
100	    private static void addParam(RequestParams result, String name, String value) {
101	        for (var reservedParameter : INTERNAL_MARKER_REQUEST_PARAMETERS) {
102	            if (reservedParameter.equalsIgnoreCase(name)) {
103	                throw new IllegalArgumentException("parameter [" + name + "] is reserved and may not be set");
104	            }
105	        }
106	        result.addValue(name, value);
107	    }
108	
109	    /**
110	     * Decodes a bit of an URL encoded by a browser.
111	     * <p>
112	     * This is equivalent to calling {@link #decodeComponent(String, Charset, boolean)}
113	     * with the UTF-8 charset (recommended to comply with RFC 3986, Section 2).
114	     *
115	     * @param s The string to decode (can be empty).
116	     * @return The decoded string, or {@code s} if there's nothing to decode.
117	     *         If the string to decode is {@code null}, returns an empty string.
118	     * @throws IllegalArgumentException if the string contains a malformed
119	     *                                  escape sequence.
120	     */
121	    public static String decodeComponent(final String s) {
122	        return decodeComponent(s, StandardCharsets.UTF_8, DECODE_PLUS_AS_SPACE);
123	    }
124	
125	    /**
126	     * Decodes a bit of an URL encoded by a browser.
127	     * <p>
128	     * The string is expected to be encoded as per RFC 3986, Section 2.
129	     * This is the encoding used by JavaScript functions {@code encodeURI}
130	     * and {@code encodeURIComponent}, but not {@code escape}.  For example
131	     * in this encoding, &eacute; (in Unicode {@code U+00E9} or in UTF-8
132	     * {@code 0xC3 0xA9}) is encoded as {@code %C3%A9} or {@code %c3%a9}.
133	     * <p>
134	     * This is essentially equivalent to calling
135	     * <code>{@link java.net.URLDecoder URLDecoder}.{@link
136	     * java.net.URLDecoder#decode(String, String)}</code>
137	     * except that it's over 2x faster and generates less garbage for the GC.
138	     * Actually this function doesn't allocate any memory if there's nothing
139	     * to decode, the argument itself is returned.
140	     *
141	     * @param s           The string to decode (can be empty).
142	     * @param charset     The charset to use to decode the string (should really
143	     *                    be {@link StandardCharsets#UTF_8}.
144	     * @param plusAsSpace Whether to decode a {@code '+'} to a single space {@code ' '}
145	     * @return The decoded string, or {@code s} if there's nothing to decode.
146	     *         If the string to decode is {@code null}, returns an empty string.
147	     * @throws IllegalArgumentException if the string contains a malformed
148	     *                                  escape sequence.
149	     */
150	    private static String decodeComponent(final String s, final Charset charset, boolean plusAsSpace) {
151	        if (s == null) {
152	            return "";
153	        }
154	        final int size = s.length();
155	        if (decodingNeeded(s, size, plusAsSpace) == false) {
156	            return s;
157	        }
158	        final byte[] buf = new byte[size];
159	        int pos = decode(s, size, buf, plusAsSpace);
160	        return new String(buf, 0, pos, charset);
161	    }
162	
163	    private static boolean decodingNeeded(String s, int size, boolean plusAsSpace) {
164	        if (Strings.isEmpty(s)) {
165	            return false;
166	        }
167	        int num = Math.min(s.length(), size);
168	        for (int i = 0; i < num; i++) {
169	            final char c = s.charAt(i);
170	            if (c == '%' || (plusAsSpace && c == '+')) {
171	                return true;
172	            }
173	        }
174	        return false;
175	    }
176	
177	    @SuppressWarnings("fallthrough")
178	    private static int decode(String s, int size, byte[] buf, boolean plusAsSpace) {
179	        int pos = 0;  // position in `buf'.
180	        for (int i = 0; i < size; i++) {
181	            char c = s.charAt(i);
182	            switch (c) {
183	                case '+':
184	                    buf[pos++] = (byte) (plusAsSpace ? ' ' : '+');  // "+" -> " "
185	                    break;
186	                case '%':
187	                    if (i == size - 1) {
188	                        throw new IllegalArgumentException("unterminated escape sequence at end of string: " + s);
189	                    }
190	                    c = s.charAt(++i);
191	                    if (c == '%') {
192	                        buf[pos++] = '%';  // "%%" -> "%"
193	                        break;
194	                    } else if (i == size - 1) {
195	                        throw new IllegalArgumentException("partial escape sequence at end of string: " + s);
196	                    }
197	                    c = decodeHexNibble(c);
198	                    final char c2 = decodeHexNibble(s.charAt(++i));
199	                    if (c == Character.MAX_VALUE || c2 == Character.MAX_VALUE) {
200	                        throw new IllegalArgumentException(
201	                            "invalid escape sequence `%" + s.charAt(i - 1) + s.charAt(i) + "' at index " + (i - 2) + " of: " + s
202	                        );
203	                    }
204	                    c = (char) (c * 16 + c2);
205	                    // Fall through.
206	                default:
207	                    buf[pos++] = (byte) c;
208	                    break;
209	            }
210	        }
211	        return pos;
212	    }
213	
214	    /**
215	     * Helper to decode half of a hexadecimal number from a string.
216	     *
217	     * @param c The ASCII character of the hexadecimal number to decode.
218	     *          Must be in the range {@code [0-9a-fA-F]}.
219	     * @return The hexadecimal value represented in the ASCII character
220	     *         given, or {@link Character#MAX_VALUE} if the character is invalid.
221	     */
222	    private static char decodeHexNibble(final char c) {
223	        if ('0' <= c && c <= '9') {
224	            return (char) (c - '0');
225	        } else if ('a' <= c && c <= 'f') {
226	            return (char) (c - 'a' + 10);
227	        } else if ('A' <= c && c <= 'F') {
228	            return (char) (c - 'A' + 10);
229	        } else {
230	            return Character.MAX_VALUE;
231	        }
232	    }
233	
234	    /**
235	     * Determine if CORS setting is a regex
236	     *
237	     * @return a corresponding {@link Pattern} if so and o.w. null.
238	     */
239	    public static Pattern checkCorsSettingForRegex(String corsSetting) {
240	        if (corsSetting == null) {
241	            return null;
242	        }
243	        int len = corsSetting.length();
244	        boolean isRegex = len > 2 && corsSetting.startsWith("/") && corsSetting.endsWith("/");
245	
246	        if (isRegex) {
247	            return Pattern.compile(corsSetting.substring(1, corsSetting.length() - 1));
248	        }
249	
250	        return null;
251	    }
252	
253	    /**
254	     * Return the CORS setting as an array of origins.
255	     *
256	     * @param corsSetting the CORS allow origin setting as configured by the user;
257	     *                    should never pass null, but we check for it anyway.
258	     * @return an array of origins if set, otherwise {@code null}.
259	     */
260	    public static String[] corsSettingAsArray(String corsSetting) {
261	        if (Strings.isNullOrEmpty(corsSetting)) {
262	            return new String[0];
263	        }
264	        return Arrays.stream(corsSetting.split(",")).map(String::trim).toArray(String[]::new);
265	    }
266	
267	    /**
268	     * Extract the trace id from the specified traceparent string.
269	     * @see <a href="https://www.w3.org/TR/trace-context/#traceparent-header">W3 traceparent spec</a>
270	     *
271	     * @param traceparent   The value from the {@code traceparent} HTTP header
272	     * @return  The trace id from the traceparent string, or {@code Optional.empty()} if it is not present.
273	     */
274	    public static Optional<String> extractTraceId(String traceparent) {
275	        return traceparent != null && traceparent.length() >= 55 ? Optional.of(traceparent.substring(3, 35)) : Optional.empty();
276	    }
277	
278	    /**
279	     * The name of the common {@code ?master_timeout} query parameter.
280	     */
281	    public static final String REST_MASTER_TIMEOUT_PARAM = "master_timeout";
282	
283	    /**
284	     * The default value for the common {@code ?master_timeout} query parameter.
285	     */
286	    public static final TimeValue REST_MASTER_TIMEOUT_DEFAULT = TimeValue.timeValueSeconds(30);
287	
288	    /**
289	     * The name of the common {@code ?timeout} query parameter.
290	     */
291	    public static final String REST_TIMEOUT_PARAM = "timeout";
292	
293	    /**
294	     * The name of the common {@code ?include_source_on_error} query parameter.
295	     * By default, the document source is included in the error response in case of parsing errors. This parameter allows to disable this.
296	     */
297	    public static final String INCLUDE_SOURCE_ON_ERROR_PARAMETER = "include_source_on_error";
298	
299	    /**
300	     * Extract the {@code ?master_timeout} parameter from the request, imposing the common default of {@code 30s} in case the parameter is
301	     * missing.
302	     *
303	     * @param restRequest The request from which to extract the {@code ?master_timeout} parameter
304	     * @return the timeout from the request, with a default of {@link #REST_MASTER_TIMEOUT_DEFAULT} ({@code 30s}) if the request does not
305	     *         specify the parameter
306	     */
307	    public static TimeValue getMasterNodeTimeout(RestRequest restRequest) {
308	        assert restRequest != null;
309	        return restRequest.paramAsTime(REST_MASTER_TIMEOUT_PARAM, REST_MASTER_TIMEOUT_DEFAULT);
310	    }
311	
312	    /**
313	     * Extract the {@code ?timeout} parameter from the request, imposing the common default of {@code 30s} in case the parameter is
314	     * missing.
315	     *
316	     * @param restRequest The request from which to extract the {@code ?timeout} parameter
317	     * @return the timeout from the request, with a default of {@link AcknowledgedRequest#DEFAULT_ACK_TIMEOUT} ({@code 30s}) if the request
318	     *         does not specify the parameter
319	     */
320	    public static TimeValue getAckTimeout(RestRequest restRequest) {
321	        assert restRequest != null;
322	        return restRequest.paramAsTime(REST_TIMEOUT_PARAM, DEFAULT_ACK_TIMEOUT);
323	    }
324	
325	    /**
326	     * Extract the {@code ?timeout} parameter from the request, returning null in case the parameter is missing.
327	     *
328	     * @param restRequest The request from which to extract the {@code ?timeout} parameter
329	     * @return the timeout from the request, with a default of {@code null} if the request does not specify the parameter
330	     */
331	    @Nullable
332	    public static TimeValue getTimeout(RestRequest restRequest) {
333	        assert restRequest != null;
334	        return restRequest.paramAsTime(REST_TIMEOUT_PARAM, null);
335	    }
336	
337	    /**
338	     * Extract the {@code ?include_source_on_error} parameter from the request, returning {@code true} in case the parameter is missing.
339	     *
340	     * @param restRequest The request from which to extract the {@code ?include_source_on_error} parameter
341	     * @return the value of the {@code ?include_source_on_error} parameter from the request, with a default of {@code true} if the request
342	     */
343	    public static boolean getIncludeSourceOnError(RestRequest restRequest) {
344	        assert restRequest != null;
345	        return restRequest.paramAsBoolean(INCLUDE_SOURCE_ON_ERROR_PARAMETER, true);
346	    }
347	
348	    // Remove the BWC support for the deprecated ?local parameter.
349	    // NOTE: ensure each usage of this method has been deprecated for long enough to remove it.
350	    @UpdateForV10(owner = UpdateForV10.Owner.DISTRIBUTED)
351	    public static void consumeDeprecatedLocalParameter(RestRequest request) {
352	        if (request.hasParam("local") == false) {
353	            return;
354	        }
355	        // Consume this param just for validation when in BWC mode.
356	        final var local = request.paramAsBoolean("local", false);
357	        if (request.getRestApiVersion() != RestApiVersion.V_8) {
358	            DeprecationLogger.getLogger(TransportLocalClusterStateAction.class)
359	                .critical(
360	                    DeprecationCategory.API,
361	                    "TransportLocalClusterStateAction-local-parameter",
362	                    "the [?local] query parameter to this API has no effect, is now deprecated, and will be removed in a future version"
363	                );
364	        }
365	    }
