708	    static class IngestStats implements ToXContentFragment {
709	
710	        final int pipelineCount;
711	        final SortedMap<String, long[]> stats;
712	
713	        IngestStats(final List<NodeStats> nodeStats) {
714	            Map<ProjectId, Set<String>> pipelineIdsByProject = new HashMap<>();
715	            SortedMap<String, long[]> stats = new TreeMap<>();
716	            for (NodeStats nodeStat : nodeStats) {
717	                if (nodeStat.getIngestStats() != null) {
718	                    Map<ProjectId, Map<String, List<ProcessorStat>>> nodeProcessorStats = nodeStat.getIngestStats().processorStats();
719	                    for (Map.Entry<ProjectId, Map<String, List<ProcessorStat>>> processorStatsForProject : nodeProcessorStats.entrySet()) {
720	                        ProjectId projectId = processorStatsForProject.getKey();
721	                        for (Map.Entry<String, List<ProcessorStat>> processorStats : processorStatsForProject.getValue().entrySet()) {
722	                            pipelineIdsByProject.computeIfAbsent(projectId, k -> new HashSet<>()).add(processorStats.getKey());
723	                            for (ProcessorStat stat : processorStats.getValue()) {
724	                                stats.compute(stat.type(), (k, v) -> {
725	                                    org.elasticsearch.ingest.IngestStats.Stats nodeIngestStats = stat.stats();
726	                                    if (v == null) {
727	                                        return new long[] {
728	                                            nodeIngestStats.ingestCount(),
729	                                            nodeIngestStats.ingestFailedCount(),
730	                                            nodeIngestStats.ingestCurrent(),
731	                                            nodeIngestStats.ingestTimeInMillis() };
732	                                    } else {
733	                                        v[0] += nodeIngestStats.ingestCount();
734	                                        v[1] += nodeIngestStats.ingestFailedCount();
735	                                        v[2] += nodeIngestStats.ingestCurrent();
736	                                        v[3] += nodeIngestStats.ingestTimeInMillis();
737	                                        return v;
738	                                    }
739	                                });
740	                            }
741	                        }
742	                    }
743	                }
744	            }
745	            this.pipelineCount = pipelineIdsByProject.values().stream().mapToInt(Set::size).sum();
746	            this.stats = Collections.unmodifiableSortedMap(stats);
747	        }
748	
749	        @Override
750	        public XContentBuilder toXContent(final XContentBuilder builder, final Params params) throws IOException {
751	            builder.startObject("ingest");
752	            {
753	                builder.field("number_of_pipelines", pipelineCount);
754	                builder.startObject("processor_stats");
755	                for (Map.Entry<String, long[]> stat : stats.entrySet()) {
756	                    long[] statValues = stat.getValue();
757	                    builder.startObject(stat.getKey());
758	                    builder.field("count", statValues[0]);
759	                    builder.field("failed", statValues[1]);
760	                    builder.field("current", statValues[2]);
761	                    builder.humanReadableField("time_in_millis", "time", new TimeValue(statValues[3], TimeUnit.MILLISECONDS));
762	                    builder.endObject();
763	                }
764	                builder.endObject();
