    private OsStats(List<NodeInfo> nodeInfos, List<NodeStats> nodeStatsList) {
        this.names = new HashMap<>();
        this.prettyNames = new HashMap<>();
        this.architectures = new HashMap<>();
        int availableProcessors = 0;
        int allocatedProcessors = 0;
        for (NodeInfo nodeInfo : nodeInfos) {
            final OsInfo osInfo = nodeInfo.getInfo(OsInfo.class);
            availableProcessors += osInfo.getAvailableProcessors();
            allocatedProcessors += osInfo.getAllocatedProcessors();

            if (osInfo.getName() != null) {
                names.merge(osInfo.getName(), 1, Integer::sum);
            }
            if (osInfo.getPrettyName() != null) {
                prettyNames.merge(osInfo.getPrettyName(), 1, Integer::sum);
            }
            if (osInfo.getArch() != null) {
                architectures.merge(osInfo.getArch(), 1, Integer::sum);
            }
        }
        this.availableProcessors = availableProcessors;
        this.allocatedProcessors = allocatedProcessors;

        long totalMemory = 0;
        long adjustedTotalMemory = 0;
        long freeMemory = 0;
        for (NodeStats nodeStats : nodeStatsList) {
            if (nodeStats.getOs() != null) {
                org.elasticsearch.monitor.os.OsStats.Mem mem = nodeStats.getOs().getMem();
                long total = mem.getTotal().getBytes();
                if (total > 0) {
                    totalMemory += total;
                }
                long adjustedTotal = mem.getAdjustedTotal().getBytes();
                if (adjustedTotal > 0) {
                    adjustedTotalMemory += adjustedTotal;
                }
                long free = mem.getFree().getBytes();
                if (free > 0) {
                    freeMemory += free;
                }
            }
        }
        this.mem = new org.elasticsearch.monitor.os.OsStats.Mem(totalMemory, adjustedTotalMemory, freeMemory);
    }

    public int getAvailableProcessors() {
        return availableProcessors;
    }

    public int getAllocatedProcessors() {
        return allocatedProcessors;
    }

    public org.elasticsearch.monitor.os.OsStats.Mem getMem() {
        return mem;
    }

    static final class Fields {
        static final String AVAILABLE_PROCESSORS = "available_processors";
        static final String ALLOCATED_PROCESSORS = "allocated_processors";
        static final String NAME = "name";
        static final String NAMES = "names";
        static final String PRETTY_NAME = "pretty_name";
        static final String PRETTY_NAMES = "pretty_names";
        static final String ARCH = "arch";
        static final String ARCHITECTURES = "architectures";
        static final String COUNT = "count";
    }

    @Override
    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
        builder.field(Fields.AVAILABLE_PROCESSORS, availableProcessors);
        builder.field(Fields.ALLOCATED_PROCESSORS, allocatedProcessors);
        writeStringCountArray(builder, Fields.NAMES, Fields.NAME, names);
        writeStringCountArray(builder, Fields.PRETTY_NAMES, Fields.PRETTY_NAME, prettyNames);
        writeStringCountArray(builder, Fields.ARCHITECTURES, Fields.ARCH, architectures);
        mem.toXContent(builder, params);
        return builder;
    }

    private static void writeStringCountArray(XContentBuilder builder, String arrayName, String keyName, Map<String, Integer> map)
        throws IOException {
        builder.startArray(arrayName);
        for (var entry : map.entrySet()) {
            builder.startObject();
            builder.field(keyName, entry.getKey());
            builder.field(Fields.COUNT, entry.getValue());
            builder.endObject();
        }
        builder.endArray();
    }
